<template>
  <div
    class="terminal-card"
    :style="{
      backgroundColor: colors.bgDark,
      border: `1px solid ${colors.border}`
    }"
  >
    <div class="linux-image">
      <img
        :src="require('@/assets/images/music/man.png')"
        loading="lazy"
        class="image"
      />
    </div>
    <TerminalHeader />

    <div
      class="terminal-body"
      :style="{ backgroundColor: colors.bg }"
    >
      <div class="prompt">
        <span :style="{ color: colors.green }">Andres@Ducuara</span>
        <span class="prompt-sep">in</span>
        <span :style="{ color: colors.blue }">~/portfolio</span>
      </div>

      <TerminalLine
        :text="typedText"
        :showCursor="showCursor"
      />

      <div class="output">
        <p :style="{ color: colors.yellow }">[INFO] Loading profile...</p>
        <p :style="{ color: colors.green }">
          [SUCCESS] Andrés Santiago Ducuara Velasquez
        </p>
        <p :style="{ color: colors.blue }">
          [ROLE] Computer Science & AI Engineer | MSc in AI
        </p>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue'
import { colors } from '@/styles/archPalette'

import TerminalHeader from '@/components/molecules/TerminalHeader.vue'
import TerminalLine from '@/components/molecules/TerminalLine.vue'

const commands = [
  'sudo pacman -S algorithms data-structures systems',
  'sudo apt install software-architecture distributed-systems',
  'sudo dnf install compilers operating-systems',
  'yay -S machine-learning neural-networks',
  'paru -S deep-learning computer-vision',
  'nix-env -iA nixpkgs.pytorch nixpkgs.scikit-learn',
  'emerge --ask scientific-computing reproducible-research',
  'sudo pacman -S statistics optimization modeling',
  'sudo apt install data-analysis causal-inference',
  'sudo pacman -S teaching pedagogy',
  'sudo apt install computational-thinking algorithms',
  'brew install academic-writing latex research-tools',
  'yay -S Math Science',
  'paru -S explainable-ai interpretability',
]

const typedText = ref('')
const showCursor = ref(true)

let commandIndex = 0
let charIndex = 0
let deleting = false

const typingSpeed = 100
const deletingSpeed = 60
const pauseAfterTyping = 1200
const pauseAfterDeleting = 400

function typeLoop() {
  const fullText = commands[commandIndex]

  if (!deleting) {
    typedText.value = fullText.slice(0, charIndex + 1)
    charIndex++

    if (typedText.value === fullText) {
      setTimeout(() => {
        deleting = true
      }, pauseAfterTyping)
    }
  } else {
    typedText.value = fullText.slice(0, charIndex - 1)
    charIndex--

    if (charIndex === 0) {
      deleting = false
      commandIndex = (commandIndex + 1) % commands.length

      setTimeout(() => {}, pauseAfterDeleting)
    }
  }

  setTimeout(
    typeLoop,
    deleting ? deletingSpeed : typingSpeed
  )
}

onMounted(() => {
  setInterval(() => {
    showCursor.value = !showCursor.value
  }, 500)

  typeLoop()
})
</script>


<style scoped>
.terminal-card {
  border-radius: 0.75rem;
  overflow: hidden;
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.6);
  font-family: "DejaVu Sans Mono", "JetBrains Mono", monospace;
  width: 50%;
  margin: 20px auto 0 auto;
}

.terminal-body {
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}


.prompt {
  display: flex;
  gap: 0.5rem;
  font-size: 0.875rem;
}

.prompt-sep {
  color: #9ca3af; 
}


.output {
  padding-left: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  font-size: 0.875rem;
  line-height: 1.4;
}

.terminal-card,
.terminal-body,
.prompt,
.output {
  transition: background-color 0.3s ease, color 0.3s ease;
}

.linux-image {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: linear-gradient(180deg, #0b0f14, #000000);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 12px;
  padding: 0.75rem;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.6);
  margin: 0 auto 0 auto;
}

.image {
  max-width: 50%;
